"""Current-scene reversible visibility of the complete unsupported U family."""
from pathlib import Path
import bpy,numpy as np,json,hashlib
NAME='MIA_v003_UnsupportedCentralLoop_HIDDEN'
def apply(folder):
 folder=Path(folder);cfg=json.loads((folder/'manifest.json').read_text());file=folder/'loop-mask.npz';assert hashlib.sha256(file.read_bytes()).hexdigest()==cfg['payload_sha256'];d=np.load(file);ob=bpy.data.objects['MIA_V17_PIXAL_DetailedHair'];m=ob.data;co=np.array([v.co[:] for v in m.vertices],np.float32);T=np.array([p.vertices[:] for p in m.polygons],np.int32);assert hashlib.sha256(co.tobytes()).hexdigest()==cfg['main_co_sha256'];assert hashlib.sha256(T.tobytes()).hexdigest()==cfg['main_topology_sha256'];ids=d['polygon_indices'];assert np.array_equal(T[ids],d['raw_vertices']);assert np.array_equal(np.array([m.attributes['MIA_SOURCE_POLYGON'].data[int(i)].value for i in ids]),d['raw_source_ids']);assert bpy.data.materials.get(NAME) is None,'Mask already installed; do not stack';original=np.array([m.polygons[int(i)].material_index for i in ids],np.int32)
 ma=bpy.data.materials.new(NAME);ma.use_nodes=True;ma.surface_render_method='DITHERED';n=ma.node_tree.nodes;n.clear();bs=n.new('ShaderNodeBsdfTransparent');out=n.new('ShaderNodeOutputMaterial');out.is_active_output=True;ma.node_tree.links.new(bs.outputs[0],out.inputs['Surface']);ma['MiaLoopPayloadSHA']=cfg['payload_sha256'];ma['MiaLoopOriginalSlots']=original.tolist();ma['MiaLoopFaceIds']=ids.tolist();ma['MiaLoopScope']='Whole natural-boundary Rear_Waves U-return skin family and its topological backing branch. Render visibility only. Raw geometry retained; exclude from later collision proxy.';slot=len(m.materials);m.materials.append(ma)
 for i in ids:m.polygons[int(i)].material_index=slot
 bpy.context.view_layer.update();return dict(material=NAME,slot=slot,whole_components=len(cfg['selected_complete_components']),backing_branch_faces=next(x['faces'] for x in cfg['parts'] if isinstance(x['component'],str)),masked_faces=len(ids),artificial_attachment_cuts=sum(x['artificial_attachment_cuts'] for x in cfg['parts']),original_slots_preserved_on_new_material=True,geometry_UV_weights_keys_fields_normals_untouched=True,native_opened=False,native_saved=False,ART=False)
def restore(folder):
 folder=Path(folder);cfg=json.loads((folder/'manifest.json').read_text());ma=bpy.data.materials[NAME];assert ma['MiaLoopPayloadSHA']==cfg['payload_sha256'];ob=bpy.data.objects['MIA_V17_PIXAL_DetailedHair'];m=ob.data;slot=next(i for i,x in enumerate(m.materials) if x==ma);co=np.array([v.co[:] for v in m.vertices],np.float32);T=np.array([p.vertices[:] for p in m.polygons],np.int32);assert hashlib.sha256(co.tobytes()).hexdigest()==cfg['main_co_sha256'];assert hashlib.sha256(T.tobytes()).hexdigest()==cfg['main_topology_sha256'];d=np.load(folder/'loop-mask.npz');assert np.array_equal(T[d['polygon_indices']],d['raw_vertices']);assert np.array_equal(np.array([m.attributes['MIA_SOURCE_POLYGON'].data[int(i)].value for i in d['polygon_indices']]),d['raw_source_ids']);assert slot==len(m.materials)-1,'An intervening hair material append requires an explicit coordinated rollback; no mutation performed'
 for i,old in zip(ma['MiaLoopFaceIds'],ma['MiaLoopOriginalSlots']):assert m.polygons[int(i)].material_index==slot;m.polygons[int(i)].material_index=int(old)
 if slot==len(m.materials)-1 and all(p.material_index!=slot for p in m.polygons):m.materials.pop(index=slot)
 bpy.data.materials.remove(ma);bpy.context.view_layer.update();return dict(restored=True,topology_and_data_unchanged=True,native_saved=False)
